package com.trough.hot;
import android.os.*;import java.io.File;import org.json.*;
/** Attack-first observation: no resting-contact prerequisite or damage injection. */
final class HalfSwordIncomingStrikeCheck implements Runnable {
 final double approachCm;double bandDistance,actualApproach;
 final HalfSwordView v;final HalfSwordAimCheck input;final HalfSwordBodyContactCheck movement;final Handler ui=new Handler(Looper.getMainLooper());final long began=SystemClock.uptimeMillis();final boolean originalGeometry;int stage,steps,geometryStep=-1;boolean complete;JSONObject geometry,before,after,nearest;final JSONArray trajectory=new JSONArray();double sx,sy,hx,hy,hz,peak,minimum=Double.POSITIVE_INFINITY;
 HalfSwordIncomingStrikeCheck(HalfSwordView view){this(view,0.);}HalfSwordIncomingStrikeCheck(HalfSwordView view,double closer){if(!Double.isFinite(closer)||closer<0||closer>20)throw new IllegalArgumentException("Approach bound");approachCm=closer;v=view;originalGeometry=v.weaponBodyObserveGeometry;input=new HalfSwordAimCheck(v);movement=new HalfSwordBodyContactCheck(v);v.weaponBodyObserveGeometry=true;}void start(){ui.postDelayed(this,150);}void need(boolean b,String why)throws Exception{if(!b)throw new Exception(why);}
 void sample(){try{JSONObject g=new JSONObject(v.secondaryBladeGeometry);int n=g.optInt("step",-1);if(g.optInt("error",-1)!=0||!g.has("gap_m")||n<=geometryStep||n>v.characterSteps+1||v.characterSteps-n>12)return;geometryStep=n;geometry=g;if(stage==6){double gap=g.getDouble("gap_m");if(gap<minimum){minimum=gap;nearest=g;}if(trajectory.length()<96)trajectory.put(g);}}catch(Exception ignored){}}
 JSONObject health()throws Exception{return new JSONObject().put("health",v.playerDamage.health).put("damage_hits",v.playerDamage.hits).put("contacts",v.opponentBladeContacts).put("swing_starts",v.opponentSwingStarts).put("steps",v.characterSteps).put("armed",v.playerDamage.armed).put("facing_applied",v.opponentFacingApplied);}
 public void run(){try{need(SystemClock.uptimeMillis()-began<25000,"Incoming strike timeout");need(v.renderVisible&&!v.characterFailed,"Scene unavailable");sample();switch(stage){
 case 0:if(v.characterRunning)input.click("Run / pause");if(v.opponentFollow)input.click("Opponent spacing · prototype");input.click("Duel setup");stage=1;break;
 case 1:if(v.resetPending())break;geometryStep=-1;geometry=null;input.click("Run / pause");steps=v.characterSteps;stage=2;break;
 case 2:if(v.characterSteps-steps<60)break;if(approachCm>0){input.click("Opponent spacing · prototype");steps=v.characterSteps;stage=20;break;}need(v.opponentFacingApplied&&geometry!=null,"Opposing geometry unavailable");{JSONArray p=input.observation().getJSONArray("pelvis_cm"),b=geometry.getJSONArray("blade_centerline_m"),t=geometry.getJSONArray("body_centerline_m");sx=p.getDouble(0);sy=p.getDouble(1);movement.targetX=sx+(b.getDouble(0)-t.getDouble(0))*100;movement.targetY=sy+(b.getDouble(2)-t.getDouble(2))*100;need(Math.hypot(movement.targetX-sx,movement.targetY-sy)<180,"Approach outside bound");}movement.bodyTowardBlade(true);steps=v.characterSteps;stage=3;break;
 case 20:if(v.characterSteps-steps<180)break;input.click("Opponent spacing · prototype");steps=v.characterSteps;stage=21;break;
 case 21:if(v.characterSteps-steps<60)break;{JSONArray p=input.observation().getJSONArray("pelvis_cm");sx=p.getDouble(0);sy=p.getDouble(1);double dx=v.opponentRootX-sx,dy=v.opponentRootY-sy;bandDistance=Math.hypot(dx,dy);need(bandDistance>100&&bandDistance<160,"Spacing baseline outside bound");need(geometry!=null&&v.characterSteps>=geometry.getInt("step")&&v.characterSteps-geometry.getInt("step")<=12,"Approach blade geometry stale");JSONArray blade=geometry.getJSONArray("blade_centerline_m"),body=geometry.getJSONArray("body_centerline_m");dx=blade.getDouble(0)-body.getDouble(0);dy=blade.getDouble(2)-body.getDouble(2);double direction=Math.hypot(dx,dy);need(Double.isFinite(direction)&&direction>.001,"Approach blade direction invalid");movement.targetX=sx+dx/direction*approachCm;movement.targetY=sy+dy/direction*approachCm;}movement.bodyTowardBlade(true);steps=v.characterSteps;stage=3;break;
 case 3:{JSONArray p=input.observation().getJSONArray("pelvis_cm");need(Math.hypot(p.getDouble(0)-sx,p.getDouble(1)-sy)<180,"Movement outside bound");if((approachCm>0?Math.hypot(p.getDouble(0)-movement.targetX,p.getDouble(1)-movement.targetY)>1.5:geometry.optDouble("gap_m",1)>.08)&&v.characterSteps-steps<180){movement.bodyTowardBlade(false);break;}}v.cancelAllTouchInputs();steps=v.characterSteps;stage=4;break;
 case 4:if(v.characterSteps-steps<60)break;need(v.roundOutcome==0&&v.playerDamage.armed,"Attack baseline not clear and rearmed");before=health();{JSONArray p=input.observation().getJSONArray("pelvis_cm");actualApproach=Math.hypot(p.getDouble(0)-sx,p.getDouble(1)-sy);before.put("pelvis_height_cm",p.getDouble(2)).put("root_distance_cm",Math.hypot(v.opponentRootX-p.getDouble(0),v.opponentRootY-p.getDouble(1)));}hx=v.opponentHandX;hy=v.opponentHandY;hz=v.opponentHandZ;minimum=Double.POSITIVE_INFINITY;input.click("Opponent swing");steps=v.characterSteps;stage=6;break;
 case 6:peak=Math.max(peak,Math.sqrt(Math.pow(v.opponentHandX-hx,2)+Math.pow(v.opponentHandY-hy,2)+Math.pow(v.opponentHandZ-hz,2)));if(v.characterSteps-steps<180&&v.roundOutcome==0)break;need(v.opponentSwingStarts==before.getInt("swing_starts")+1&&!v.opponentSwingActive&&peak>10,"Physical opponent swing incomplete");after=health();if(v.characterRunning)input.click("Run / pause");input.pausedSteps=-1;stage=7;break;
 case 7:if(!input.pausedScene(true))break;complete=true;finish(null);return;
 }ui.postDelayed(this,50);}catch(Throwable error){v.characterRunning=false;v.cancelAllTouchInputs();v.refreshRunControl();finish(error.toString());}}
 void finish(String error){v.weaponBodyObserveGeometry=originalGeometry;try{JSONObject o=new JSONObject().put("approach_direction","current-blade-body-horizontal").put("geometry_monitor_restored",v.weaponBodyObserveGeometry==originalGeometry).put("approach_from_spacing_cm",approachCm).put("spacing_baseline_distance_cm",bandDistance).put("actual_player_approach_cm",actualApproach).put("passed",complete&&error==null).put("error",error==null?"":error).put("stage",stage).put("before",before==null?JSONObject.NULL:before).put("after",after==null?JSONObject.NULL:after).put("damage_verified",before!=null&&after!=null&&after.optInt("health",100)<before.optInt("health",100)&&after.optInt("damage_hits",0)>before.optInt("damage_hits",0)).put("hand_motion_cm",peak).put("minimum_attack_gap_m",Double.isFinite(minimum)?minimum:JSONObject.NULL).put("nearest_attack_geometry",nearest==null?JSONObject.NULL:nearest).put("trajectory",trajectory).put("last_geometry",geometry==null?JSONObject.NULL:geometry).put("module",HalfSwordBridge.loadedModuleSha256).put("time_ms",System.currentTimeMillis()).put("scope","Measured opposing approach and one physical swing; pass means completed observation, damage requires separate health/hit deltas. No pose/health injection or adaptive AI.");Payloads.writeSmall(new File(v.getContext().getFilesDir(),"home/.trough/half-sword-incoming-strike-check-result.json"),o.toString());}catch(Exception ignored){}}
}
